    pub(crate) fn compare_socket_address(
        &self,
        other: &Document,
        a: &SocketAddress,
        b: &SocketAddress,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        if a.get_allowed_i_pv6_ext_headers_ref() != b.get_allowed_i_pv6_ext_headers_ref() {
            return Err(format!("{path}: ALLOWED_I_PV6_EXT_HEADERS_REF mismatch"));
        }
        if a.get_allowed_tcp_options_ref() != b.get_allowed_tcp_options_ref() {
            return Err(format!("{path}: ALLOWED_TCP_OPTIONS_REF mismatch"));
        }
        if a.get_application_endpoint() != b.get_application_endpoint() {
            return Err(format!("{path}: APPLICATION_ENDPOINT mismatch"));
        }
        if a.get_connector_ref() != b.get_connector_ref() {
            return Err(format!("{path}: CONNECTOR_REF mismatch"));
        }
        if a.get_differentiated_service_field() != b.get_differentiated_service_field() {
            return Err(format!("{path}: DIFFERENTIATED_SERVICE_FIELD mismatch"));
        }
        if a.get_flow_label() != b.get_flow_label() {
            return Err(format!("{path}: FLOW_LABEL mismatch"));
        }
        let list_a = a.get_multicast_connector_refs();
        let list_b = b.get_multicast_connector_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MULTICAST_CONNECTOR_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.MULTICAST_CONNECTOR_REFS[{index}] mismatch"));
            }
        }
        if a.get_path_mtu_discovery_enabled() != b.get_path_mtu_discovery_enabled() {
            return Err(format!("{path}: PATH_MTU_DISCOVERY_ENABLED mismatch"));
        }
        if a.get_pdu_collection_max_buffer_size() != b.get_pdu_collection_max_buffer_size() {
            return Err(format!("{path}: PDU_COLLECTION_MAX_BUFFER_SIZE mismatch"));
        }
        if a.get_pdu_collection_timeout() != b.get_pdu_collection_timeout() {
            return Err(format!("{path}: PDU_COLLECTION_TIMEOUT mismatch"));
        }
        let list_a = a.get_static_socket_connections();
        let list_b = b.get_static_socket_connections();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: STATIC_SOCKET_CONNECTIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.static_socket_connections.get(*x).ok_or_else(|| {
                format!("{path}.STATIC_SOCKET_CONNECTIONS[{index}]: id not found in own arena")
            })?;
            let y = other.static_socket_connections.get(*y).ok_or_else(|| {
                format!("{path}.STATIC_SOCKET_CONNECTIONS[{index}]: id not found in other arena")
            })?;
            self.compare_static_socket_connection(
                other,
                x,
                y,
                &format!("{path}.STATIC_SOCKET_CONNECTIONS[{index}]"),
            )?;
        }
        if a.get_udp_checksum_handling() != b.get_udp_checksum_handling() {
            return Err(format!("{path}: UDP_CHECKSUM_HANDLING mismatch"));
        }
        Ok(())
    }

