    pub(crate) fn compare_static_socket_connection(
        &self,
        other: &Document,
        a: &StaticSocketConnection,
        b: &StaticSocketConnection,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_i_pdu_identifier_refs();
        let list_b = b.get_i_pdu_identifier_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: I_PDU_IDENTIFIER_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!("{path}.I_PDU_IDENTIFIER_REFS[{index}] mismatch"));
            }
        }
        if a.get_remote_address_ref() != b.get_remote_address_ref() {
            return Err(format!("{path}: REMOTE_ADDRESS_REF mismatch"));
        }
        if a.get_tcp_connect_timeout() != b.get_tcp_connect_timeout() {
            return Err(format!("{path}: TCP_CONNECT_TIMEOUT mismatch"));
        }
        if a.get_tcp_role() != b.get_tcp_role() {
            return Err(format!("{path}: TCP_ROLE mismatch"));
        }
        Ok(())
    }
